<?php
require_once __DIR__ . '/../includes/auth.php';$u=require_role(['user']);$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$action=$_POST['action']??'';$s=$pdo->prepare("SELECT * FROM lost_items WHERE id=? AND posted_by=?");$s->execute([$id,$u['id']]);$it=$s->fetch();if($it){$old=$it['status'];if($action==='cancel' && in_array($old,['Lost','Not Found'],true)){$pdo->prepare("UPDATE lost_items SET status='Cancelled' WHERE id=? AND posted_by=?")->execute([$id,$u['id']]);$new='Cancelled';}elseif($action==='notfound' && $old==='Lost'){$pdo->prepare("UPDATE lost_items SET status='Not Found' WHERE id=? AND posted_by=?")->execute([$id,$u['id']]);$new='Not Found';}elseif($action==='found' && in_array($old,['Lost','Not Found'],true)){$pdo->prepare("UPDATE lost_items SET status='Found' WHERE id=? AND posted_by=?")->execute([$id,$u['id']]);$new='Found';}else $new=$old;if($new!==$old){$pdo->prepare("INSERT INTO item_history(item_id,changed_by,old_status,new_status,action_description) VALUES(?,?,?,?,?)")->execute([$id,$u['id'],$old,$new,'Owner updated item status']);$msg='Item status updated.';}}}
$s=$pdo->prepare("SELECT * FROM lost_items WHERE posted_by=? ORDER BY created_at DESC");$s->execute([$u['id']]);$items=$s->fetchAll();page_header('My Items');?><h1>My Item Posts</h1><?php if($msg):?><div class="alert success"><?=e($msg)?></div><?php endif;?><p><a class="btn" href="add-item.php">+ Add Item</a></p>
<div class="table-wrap"><table><tr><th>Item</th><th>Status</th><th>Date Posted</th><th>Actions</th></tr><?php foreach($items as $it):?><tr><td><?=e($it['item_name'])?></td><td><?=e($it['status'])?></td><td><?=e($it['created_at'])?></td><td class="actions"><?php if(in_array($it['status'],['Lost','Not Found'],true)):?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$it['id']?>"><input type="hidden" name="action" value="notfound"><button class="small light">Not Found</button></form><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$it['id']?>"><input type="hidden" name="action" value="found"><button class="small">Found</button></form><form method="post" data-confirm="Cancel this post?"><?=csrf_field()?><input type="hidden" name="id" value="<?=$it['id']?>"><input type="hidden" name="action" value="cancel"><button class="small danger">Cancel</button></form><?php endif;?></td></tr><?php endforeach;?></table></div><?php page_footer();?>
